  "fvocab-29": {"prompt": "Comment dit-on 'mes' en français?", "promptNative": "Come si dice 'mes' in francese?", "explain": "'month' si dice 'le mois'."},
  "fvocab-30": {"promptNative": "'L'heure' significa...", "options": ["ora; ora del giorno", "braccio", "finestra", "naso"], "explain": "'L'heure' significa ora; ora del giorno."},
